-- ============================================================================
-- Migration 017: Class 10 Science Ch1 question bank (207 questions)
-- Generated by scripts/qbank_ch1/build_017.js - do not edit by hand.
-- Source: docs/imports/ch1-class10-science/*.csv
--
-- Idempotent: deterministic sha1-derived UUIDs, every write is an upsert, and
-- every row carries its CSV id in the new questions.legacy_id column, so a
-- re-run updates rows instead of duplicating them.
--
-- Safety: every question lands as engine_status='draft' / status='draft' /
-- is_verified=false. This migration never publishes anything - review and
-- publishing are manual steps in /admin/questions.
--
-- Depends on: 013 (engine columns, subtopics, question_answers, question_tags,
-- question_stats) and 012 (questions.status).
-- Contents: 7 topics, 28 subtopics, 7 case passages,
-- 207 questions, 576 options.
-- ============================================================================

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname='engine_question_type') THEN
    RAISE EXCEPTION 'migration 013 must be applied before 017';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='questions' AND column_name='status') THEN
    RAISE EXCEPTION 'migration 012 must be applied before 017';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM chapters ch JOIN subjects s ON ch.subject_id=s.id
      JOIN classes c ON s.class_id=c.id JOIN boards b ON c.board_id=b.id
    WHERE b.code='cbse' AND c.code='class-10' AND s.code='science' AND ch.code='chemical-reactions'
  ) THEN
    RAISE EXCEPTION 'target chapter cbse/class-10/science/chemical-reactions not found (migration 003)';
  END IF;
END $$;

-- Stable external key for idempotent re-imports and for the review queue.
ALTER TABLE questions ADD COLUMN IF NOT EXISTS legacy_id TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_questions_legacy_id
  ON questions(legacy_id) WHERE legacy_id IS NOT NULL;

-- Legacy lookup rows the engine maps to (003/014 may not have created them).
INSERT INTO question_types (code,name,description,sort_order) VALUES
  ('descriptive','Descriptive','Short/long written answer',12),
  ('equation_balancing','Equation Balancing','Write and balance equations',13)
ON CONFLICT (code) DO NOTHING;
INSERT INTO difficulty_levels (code,name,weight,color,sort_order) VALUES
  ('easy','Easy',1.0,'#22c55e',1),('medium','Medium',2.0,'#f59e0b',2),('hard','Hard',3.0,'#ef4444',3)
ON CONFLICT (code) DO NOTHING;

