-- 10. Post-import report (surfaced as a NOTICE by supabase db push)
DO $$
DECLARE v_q INT; v_pass INT; v_opt INT; v_ans INT; v_draft INT; v_pub INT;
BEGIN
  SELECT COUNT(*) INTO v_q    FROM questions WHERE legacy_id LIKE 'CR-%';
  SELECT COUNT(*) INTO v_pass FROM questions WHERE legacy_id LIKE 'CP-%';
  SELECT COUNT(*) INTO v_opt  FROM question_options o JOIN questions q ON q.id=o.question_id WHERE q.legacy_id LIKE 'CR-%';
  SELECT COUNT(*) INTO v_ans  FROM question_answers a JOIN questions q ON q.id=a.question_id WHERE q.legacy_id LIKE 'CR-%';
  SELECT COUNT(*) INTO v_draft FROM questions WHERE legacy_id LIKE 'CR-%' AND engine_status='draft';
  SELECT COUNT(*) INTO v_pub  FROM questions WHERE legacy_id LIKE 'CR-%' AND engine_status='published';
  RAISE NOTICE 'QBANK017: questions=% passages=% options=% answers=% draft=% published=%', v_q, v_pass, v_opt, v_ans, v_draft, v_pub;
END $$;
